function sheetTableRows({ values }) {
  if (!Array.isArray(values) || values.some((row) => !Array.isArray(row)))
    throw new Error("Expected the sheet range as rows of cell values");
  for (const row of values)
    for (const cell of row)
      if (
        cell !== null &&
        typeof cell !== "string" &&
        typeof cell !== "boolean" &&
        !(typeof cell === "number" && Number.isFinite(cell))
      )
        throw new Error("The sheet returned an invalid cell value");
  if (!values.length) return { rows: [] };
  const headers = values[0],
    rows = [];
  for (const cells of values.slice(1)) {
    const row = Object.create(null);
    for (let column = 0; column < cells.length; column++) {
      const header = headers[column];
      if (header) row[String(header)] = cells[column];
    }
    if (Object.keys(row).length) rows.push(row);
  }
  return { rows };
}

export default function (input) {
  const { rows } = sheetTableRows(input);
  if (rows.length > 250)
    throw new Error("Choose a range containing at most250contacts for one enrichment batch");
  return { rows, count: rows.length, hasContacts: rows.length > 0 };
}

