export default function sheetDropcontactContacts({ rows }) {
  if (!Array.isArray(rows) || rows.length === 0)
    throw new Error("Expected the complete spreadsheet rows");
  if (rows.length > 250)
    throw new Error(
      "The source submits one enrichment batch; choose a range containing at most 250 contacts before running",
    );
  const fields = {
    email: "email",
    firstName: "first_name",
    lastName: "last_name",
    fullName: "full_name",
    companyName: "company",
    website: "website",
    LinkedIn: "linkedin",
  };
  const data = rows.map((row, index) => {
    if (!row || typeof row !== "object" || Array.isArray(row))
      throw new Error("Invalid spreadsheet contact at row " + (index + 2));
    const contact = {};
    for (const [column, field] of Object.entries(fields)) {
      const value = row[column];
      if (value === undefined || value === null || value === "") continue;
      if (typeof value !== "string")
        throw new Error("Contact column " + column + " must contain text at row " + (index + 2));
      if (value.trim()) contact[field] = value;
    }
    if (!(
      contact.email ||
      contact.linkedin ||
      ((contact.company || contact.website) &&
        ((contact.first_name && contact.last_name) || contact.full_name))
    ))
      throw new Error(
        "Contact row " + (index + 2) + " needs email, LinkedIn, or a name and company/website",
      );
    return contact;
  });
  return { data, count: data.length, hasContacts: data.length > 0 };
}

