export default function lemlistLeadProgress({
  plans,
  expectedCount,
  previousState,
  statusCode,
  body,
  bodyEncoding,
}) {
  if (expectedCount === 0 && (plans === null || plans === undefined)) plans = [];
  if (!Array.isArray(plans) || plans.length !== expectedCount || plans.length > 250)
    throw new Error("Expected the complete Lemlist lead plan");
  let state;
  if (previousState === null || previousState === undefined) state = { index: 0, leads: [] };
  else {
    if (
      !Number.isInteger(previousState.index) ||
      previousState.index < 0 ||
      previousState.index >= plans.length ||
      !Array.isArray(previousState.leads) ||
      previousState.leads.length !== previousState.index
    )
      throw new Error("Invalid Lemlist lead progress");
    if (
      !Number.isInteger(statusCode) ||
      statusCode < 200 ||
      statusCode >= 300 ||
      (bodyEncoding !== null && bodyEncoding !== undefined) ||
      !body ||
      typeof body !== "object" ||
      Array.isArray(body) ||
      typeof body._id !== "string" ||
      !body._id.trim()
    )
      throw new Error(
        "Lemlist did not confirm the created lead; this or earlier leads may already exist",
      );
    if (
      body.email !== undefined &&
      (typeof body.email !== "string" ||
        body.email.toLowerCase() !== plans[previousState.index].email.toLowerCase())
    )
      throw new Error(
        "Lemlist returned a different lead email; creation may already have occurred",
      );
    state = { index: previousState.index + 1, leads: previousState.leads.concat([body]) };
  }
  const more = state.index < plans.length;
  return {
    state,
    more,
    endpoint: more ? plans[state.index].endpoint : "",
    body: more ? plans[state.index].body : {},
    count: state.leads.length,
  };
}

